SELECT COUNT(DISTINCT struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR)) AS "count_result" FROM triples t0, triples t1, triples t2, triples t3, triples t4, triples t5, triples t6, triples t7 WHERE t0.p = 'http://xmlns.com/foaf/homepage' AND struct_pack(kind := 0::UTINYINT, value := t1.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t1.p = 'http://ogp.me/ns#title' AND struct_pack(kind := 0::UTINYINT, value := t2.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t2.p = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type' AND struct_pack(kind := 0::UTINYINT, value := t3.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t3.p = 'http://schema.org/caption' AND struct_pack(kind := 0::UTINYINT, value := t4.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t4.p = 'http://schema.org/description' AND struct_pack(kind := 0::UTINYINT, value := t5.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = t0.o AND t5.p = 'http://schema.org/url' AND struct_pack(kind := 0::UTINYINT, value := t6.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = t0.o AND t6.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/hits' AND struct_pack(kind := 0::UTINYINT, value := t7.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t7.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/hasGenre' AND t7.o = struct_pack(kind := 0::UTINYINT, value := 'http://db.uwaterloo.ca/~galuc/wsdbm/SubGenre83', datatype := NULL::VARCHAR, lang := NULL::VARCHAR)